        if (scl_i_q && !scl_i)  event_scl_interference_o = 1'b1;
        if (scl_i_q && scl_i && (sda_i_q != sda_i)) begin
          // Unexpected Stop / Start
          event_sda_unstable_o = 1'b1;
        end
      end
